<script setup lang="ts">
definePageMeta({middleware:'auth'});useHead({title:'آدرس‌های من'});const{api}=useShopApi();const{data:addresses,refresh}=await useAsyncData('my-addresses',()=>api<any[]>('/addresses'));const{data:provinces}=await useAsyncData('address-provinces',()=>api<any[]>('/locations/provinces'));const blank=()=>({title:'خانه',receiver_name:'',receiver_mobile:'',province_id:null as number|null,city_id:null as number|null,address:'',postal_code:'',is_default:false}),form=reactive(blank()),cities=ref<any[]>([]),editing=ref<number|null>(null),open=ref(false),error=ref('');
watch(()=>form.province_id,async id=>{if(!id){cities.value=[];return}cities.value=await api<any[]>(`/locations/cities?province_id=${id}`);if(!cities.value.some(x=>x.id===form.city_id))form.city_id=null});
async function edit(item:any){editing.value=item.id;open.value=true;Object.assign(form,item);cities.value=await api<any[]>(`/locations/cities?province_id=${item.province_id}`)}function reset(){editing.value=null;open.value=false;Object.assign(form,blank());error.value=''}
async function save(){error.value='';try{await api(`/addresses${editing.value?'/'+editing.value:''}`,{method:editing.value?'PUT':'POST',body:form});reset();await refresh()}catch(e:any){error.value=e?.data?.message||Object.values(e?.data?.errors||{})[0]?.[0]||'ذخیره آدرس انجام نشد.'}}async function remove(id:number){if(confirm('این آدرس حذف شود؟')){await api(`/addresses/${id}`,{method:'DELETE'});refresh()}}async function makeDefault(item:any){await api(`/addresses/${item.id}`,{method:'PUT',body:{...item,is_default:true}});refresh()}
</script>
<template><div class="mx-auto max-w-6xl px-4 py-10"><div class="flex items-center justify-between"><div><h1 class="text-2xl font-black">آدرس‌های من</h1><p class="mt-2 text-sm text-slate-500">آدرس‌های تحویل سفارش را مدیریت کنید.</p></div><button class="rounded-xl bg-brand-700 px-5 py-3 font-bold text-white" @click="open=true">آدرس جدید</button></div><form v-if="open" class="mt-6 grid gap-4 rounded-2xl border bg-white p-5 sm:grid-cols-2" @submit.prevent="save"><p v-if="error" class="rounded-xl bg-rose-50 p-3 text-sm text-rose-700 sm:col-span-2">{{error}}</p><input v-model="form.title" class="h-11 rounded-xl border px-3" placeholder="عنوان آدرس، مثل خانه"><input v-model="form.receiver_name" required class="h-11 rounded-xl border px-3" placeholder="نام تحویل‌گیرنده"><input v-model="form.receiver_mobile" required dir="ltr" class="h-11 rounded-xl border px-3 text-left" placeholder="شماره موبایل"><input v-model="form.postal_code" required dir="ltr" maxlength="10" class="h-11 rounded-xl border px-3 text-left" placeholder="کد پستی"><select v-model="form.province_id" required class="h-11 rounded-xl border bg-white px-3"><option :value="null">انتخاب استان</option><option v-for="p in provinces" :key="p.id" :value="p.id">{{p.name}}</option></select><select v-model="form.city_id" required :disabled="!form.province_id" class="h-11 rounded-xl border bg-white px-3"><option :value="null">انتخاب شهر</option><option v-for="c in cities" :key="c.id" :value="c.id">{{c.name}}</option></select><textarea v-model="form.address" required rows="3" class="rounded-xl border p-3 sm:col-span-2" placeholder="نشانی کامل"/><label class="flex items-center gap-2 text-sm font-bold"><input v-model="form.is_default" type="checkbox" class="accent-brand-700">آدرس پیش‌فرض باشد</label><div class="flex justify-end gap-2"><button type="button" class="rounded-xl border px-5" @click="reset">انصراف</button><button class="rounded-xl bg-brand-700 px-6 font-bold text-white">ذخیره آدرس</button></div></form><div v-if="addresses?.length" class="mt-6 grid gap-4 md:grid-cols-2"><article v-for="item in addresses" :key="item.id" class="rounded-2xl border bg-white p-5"><div class="flex justify-between"><b>{{item.title}}</b><span v-if="item.is_default" class="rounded-lg bg-emerald-50 px-2 py-1 text-xs font-bold text-emerald-700">پیش‌فرض</span></div><p class="mt-3 text-sm font-bold">{{item.receiver_name}} · {{item.receiver_mobile}}</p><p class="mt-2 text-sm leading-7 text-slate-500">{{item.province}}، {{item.city}}، {{item.address}}</p><p class="mt-1 text-xs text-slate-400">کد پستی: {{item.postal_code}}</p><div class="mt-4 flex gap-4 border-t pt-4 text-xs font-bold"><button class="text-brand-700" @click="edit(item)">ویرایش</button><button v-if="!item.is_default" class="text-emerald-700" @click="makeDefault(item)">انتخاب به‌عنوان پیش‌فرض</button><button class="mr-auto text-rose-600" @click="remove(item.id)">حذف</button></div></article></div><div v-else-if="!open" class="mt-6 rounded-2xl border border-dashed bg-white p-12 text-center text-slate-400">هنوز آدرسی ثبت نکرده‌اید.</div></div></template>
